#pragma once

/*=============================================================================
	MemoryPatch.hpp: Direct edits to the loaded image.

	Where Interception.hpp redirects a function, this rewrites bytes in place.
	It is the blunt instrument, for the cases reflection and detours cannot
	reach: a hard-coded constant, a check to disable, a call to erase.

	Every entry point takes an image-relative address - the offset a
	disassembler shows - and rebases it onto the running module for you, so a
	patch list reads as a list of offsets and nothing else:

	    FImageMemory::Patch<bool>(0x10512933, false);
	    FImageMemory::Null(0x31BEF70);

	Nothing here records what it displaced, so a patch cannot be taken back.
	Read() first if the previous value matters.

	Generated by Dumper-7. Do not edit.
=============================================================================*/

#include <cstddef>
#include <cstdint>
#include <cstring>
#include <initializer_list>
#include <type_traits>

#include "Interception.hpp"

namespace UE::Memory
{
	using uint8 = std::uint8_t;
	using uint32 = std::uint32_t;
	using uint64 = std::uint64_t;
	using SIZE_T = std::size_t;

	/*-----------------------------------------------------------------------------
		FImageMemory
	-----------------------------------------------------------------------------*/

	/**
	 * Reads and writes the loaded image by image-relative address.
	 *
	 * Every write makes the page writable for exactly as long as it takes, restores the protection
	 * afterwards, and flushes the instruction cache - so patching code is as safe as patching data.
	 * A write that falls outside the module, wholly or partly, is refused rather than attempted:
	 * an offset from the wrong build is caught here instead of corrupting whatever it landed on.
	 *
	 * Each entry point takes an optional module name, defaulting to the executable itself.
	 */
	class FImageMemory
	{
	public:
		/*-------------------------------------------------------------------------
			Addresses
		-------------------------------------------------------------------------*/

		/** Run-time address of an image-relative offset, or nullptr when it is not inside the module. */
		static void* Resolve(uint64 RelativeVirtualAddress, const wchar_t* ModuleName = nullptr);

		/** Whether Size bytes starting at RelativeVirtualAddress lie inside the module. */
		static bool IsInImage(uint64 RelativeVirtualAddress, SIZE_T Size, const wchar_t* ModuleName = nullptr);

		/*-------------------------------------------------------------------------
			Writing
		-------------------------------------------------------------------------*/

		/**
		 * Overwrites the object at RelativeVirtualAddress with Value.
		 *
		 *     FImageMemory::Patch<bool>(0x10512933, false);
		 *     FImageMemory::Patch<float>(0x1075FF2C, 1.0f);
		 *
		 * Name the type explicitly. The width of the write is sizeof(T), and letting that be deduced
		 * from an untyped literal is how a four-byte field ends up taking an eight-byte write.
		 */
		template<typename T>
		static bool Patch(uint64 RelativeVirtualAddress, const T& Value, const wchar_t* ModuleName = nullptr)
		{
			static_assert(std::is_trivially_copyable_v<T>,
				"Patch writes an object's bytes into the image, which is only meaningful for a trivially copyable type.");

			return PatchBytes(RelativeVirtualAddress, &Value, sizeof(T), ModuleName);
		}

		/**
		 * Overwrites a run of bytes, written out as opcodes.
		 *
		 *     FImageMemory::Patch(0x1F2CD64, { 0x31, 0xC0, 0xC3 });   // xor eax, eax; ret
		 */
		static bool Patch(uint64 RelativeVirtualAddress, std::initializer_list<uint8> Bytes, const wchar_t* ModuleName = nullptr);

		/** The same, from a buffer. */
		static bool PatchBytes(uint64 RelativeVirtualAddress, const void* Bytes, SIZE_T Size, const wchar_t* ModuleName = nullptr);

		/** Fills Size bytes with 0x90, for stepping over an instruction without changing what follows it. */
		static bool Nop(uint64 RelativeVirtualAddress, SIZE_T Size, const wchar_t* ModuleName = nullptr);

		/*-------------------------------------------------------------------------
			Disabling functions
		-------------------------------------------------------------------------*/

		/**
		 * Turns the function at RelativeVirtualAddress into an immediate 'ret', so calling it does
		 * nothing and returns at once.
		 *
		 *     FImageMemory::Null(0x31BEF70);
		 *
		 * The caller is untouched and cleans up its own arguments, so this is safe for a function
		 * whose return value is ignored. When the return value is read, use NullReturning() instead -
		 * a bare 'ret' leaves whatever happened to be in RAX behind as the result.
		 */
		static bool Null(uint64 RelativeVirtualAddress, const wchar_t* ModuleName = nullptr);

		/**
		 * Turns the function at RelativeVirtualAddress into 'return Value', for an integer, bool or
		 * pointer-sized result.
		 *
		 *     FImageMemory::NullReturning(0x31BEF70, 0);   // false, nullptr, 0
		 *     FImageMemory::NullReturning(0x31BEF70, 1);   // true
		 *
		 * Zero is written as 'xor eax, eax; ret', which also clears the upper half of RAX and so
		 * reads correctly as a null pointer or a 64-bit zero.
		 */
		static bool NullReturning(uint64 RelativeVirtualAddress, uint32 Value, const wchar_t* ModuleName = nullptr);

		/*-------------------------------------------------------------------------
			Reading
		-------------------------------------------------------------------------*/

		/** Copies the object at RelativeVirtualAddress out. Fails, leaving OutValue alone, if it is out of range. */
		template<typename T>
		static bool Read(uint64 RelativeVirtualAddress, T& OutValue, const wchar_t* ModuleName = nullptr)
		{
			static_assert(std::is_trivially_copyable_v<T>,
				"Read copies an object's bytes out of the image, which is only meaningful for a trivially copyable type.");

			return ReadBytes(RelativeVirtualAddress, &OutValue, sizeof(T), ModuleName);
		}

		/** The same, returning a default-constructed T when the offset is out of range. */
		template<typename T>
		static T Read(uint64 RelativeVirtualAddress, const wchar_t* ModuleName = nullptr)
		{
			T Value{};
			Read<T>(RelativeVirtualAddress, Value, ModuleName);

			return Value;
		}

		/** The same, from a buffer. */
		static bool ReadBytes(uint64 RelativeVirtualAddress, void* OutBytes, SIZE_T Size, const wchar_t* ModuleName = nullptr);
	};
}
